// =============================================================================
//  search.js — full-text search with ZERO external dependencies.
//  Fetches the site's /index.json (generated by Hugo) and does token-based
//  matching across title, description, tags, and body text. Kept deliberately
//  simple so there's nothing to update or pin.
// =============================================================================
(function () {
  "use strict";

  var input = document.getElementById("search-input");
  var results = document.getElementById("search-results");
  if (!input || !results) return;

  var index = [];
  var loaded = false;

  // Read ?q= from the URL so shared search links work.
  var params = new URLSearchParams(window.location.search);
  var initial = params.get("q") || "";

  function loadIndex() {
    if (loaded) return Promise.resolve();
    return fetch("/index.json")
      .then(function (r) { return r.json(); })
      .then(function (data) { index = data; loaded = true; });
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function highlight(text, terms) {
    var out = escapeHtml(text);
    terms.forEach(function (t) {
      if (!t) return;
      var re = new RegExp("(" + t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + ")", "ig");
      out = out.replace(re, "<mark>$1</mark>");
    });
    return out;
  }

  // Pull a short snippet of body text around the first matched term.
  function snippet(content, terms) {
    if (!content) return "";
    var lower = content.toLowerCase();
    var pos = -1;
    for (var i = 0; i < terms.length; i++) {
      var p = lower.indexOf(terms[i]);
      if (p !== -1 && (pos === -1 || p < pos)) pos = p;
    }
    if (pos === -1) return content.slice(0, 160) + "…";
    var start = Math.max(0, pos - 60);
    var end = Math.min(content.length, pos + 100);
    return (start > 0 ? "…" : "") + content.slice(start, end) + (end < content.length ? "…" : "");
  }

  function score(item, terms) {
    var s = 0;
    var title = (item.title || "").toLowerCase();
    var desc = (item.description || "").toLowerCase();
    var tags = (item.tags || []).join(" ").toLowerCase();
    var body = (item.content || "").toLowerCase();
    terms.forEach(function (t) {
      if (title.indexOf(t) !== -1) s += 10;
      if (desc.indexOf(t) !== -1) s += 4;
      if (tags.indexOf(t) !== -1) s += 4;
      if (body.indexOf(t) !== -1) s += 1;
    });
    return s;
  }

  function render(query) {
    var terms = query.toLowerCase().split(/\s+/).filter(Boolean);
    if (!terms.length) {
      results.innerHTML = '<li class="search-empty">Type to search writeups, projects, and notes…</li>';
      return;
    }
    var matches = index
      .map(function (item) { return { item: item, s: score(item, terms) }; })
      .filter(function (m) { return m.s > 0; })
      .sort(function (a, b) { return b.s - a.s; })
      .slice(0, 30);

    if (!matches.length) {
      results.innerHTML = '<li class="search-empty">No results for “' + escapeHtml(query) + '”.</li>';
      return;
    }

    results.innerHTML = matches.map(function (m) {
      var it = m.item;
      var section = it.section ? '<span class="badge">' + escapeHtml(it.section) + "</span>" : "";
      return (
        '<li class="post-item">' +
          '<div class="badges" style="margin-bottom:.4rem">' + section +
            (it.difficulty ? '<span class="badge diff diff-' + it.difficulty.toLowerCase() + '">' + escapeHtml(it.difficulty) + "</span>" : "") +
          "</div>" +
          '<h3><a href="' + it.url + '">' + highlight(it.title, terms) + "</a></h3>" +
          '<p class="excerpt">' + highlight(snippet(it.content || it.description || "", terms), terms) + "</p>" +
        "</li>"
      );
    }).join("");
  }

  var timer;
  function onInput() {
    clearTimeout(timer);
    var q = input.value;
    timer = setTimeout(function () {
      loadIndex().then(function () { render(q); });
    }, 120);
  }

  input.addEventListener("input", onInput);
  // Focus the box on load for a search-first page.
  loadIndex().then(function () {
    if (initial) { input.value = initial; render(initial); }
    else { render(""); }
  });
  input.focus();
})();
